SELECT c.*, t.name as teacher_name, s.name as semester_name FROM course c LEFT JOIN teacher t ON c.teacher_id = t.id LEFT JOIN semester s ON c.semester_id = s.id
AND c.name LIKE CONCAT('%', #{name}, '%')
AND c.teacher_id = #{teacherId}
AND c.semester_id = #{semesterId}
ORDER BY c.id DESC

